const suggestions = $json.geoTargetConstantSuggestions || [];
const seen = new Set();
const output = [];
for (const s of suggestions) {
  const gtc = s.geoTargetConstant;
  if (!gtc || !gtc.resourceName || seen.has(gtc.resourceName)) continue;
  seen.add(gtc.resourceName);
  output.push({
    json: {
      resourceName: gtc.resourceName,
      name: gtc.name,
      canonicalName: gtc.canonicalName,
      countryCode: gtc.countryCode,
      targetType: gtc.targetType,
    },
  });
  if (output.length >= 8) break;
}
return output;
